(function () {
  'use strict';
  // Inventory analysis.
  //   Average inventory = (beginning + ending) / 2 (at cost).
  //   Turnover = COGS / average inventory; days on hand = days per year / turnover.
  //   GMROI = gross margin $ / average inventory at cost = (sales - COGS) / average inventory.
  //   EOQ (Wilson formula) = sqrt(2 x D x S / H), D = annual units, S = cost per order,
  //   H = unit cost x holding % per year. Orders a year = D / Q; ordering cost = (D / Q) x S;
  //   holding cost = (Q / 2 + safety stock) x H.
  //   Reorder point = daily demand x lead time + safety stock, daily demand = D / selling days,
  //   rounded up to a whole unit.
  // Verified (scratchpad b4biz/ia.test.js): textbook EOQ D = 12,000, S = $75, H = $5 -> sqrt(360,000)
  //   = 600 units, 20 orders a year, ordering cost = cycle holding cost = $1,500 (equal at the EOQ,
  //   as theory requires); second textbook case D = 1,000, S = $10, H = $0.50 -> 200 units.
  //   Reorder point 12,000 / 365 x 10 + 200 = 528.8 -> 529 units. Turnover: COGS $900,000 /
  //   average $150,000 = 6.0x, 60.8 days; GMROI $600,000 / $150,000 = 4.00.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var money2 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var units = new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 });
  var one = new Intl.NumberFormat('en-US', { minimumFractionDigits: 1, maximumFractionDigits: 1 });

  function set(id, text) { document.getElementById(id).textContent = text; }
  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }

  function performance(sales, cogs, begin, end, days) {
    var avg = (begin + end) / 2;
    if (avg <= 0) return { avg: avg, turns: NaN, doh: NaN, gmroi: NaN };
    var turns = cogs / avg;
    return { avg: avg, turns: turns, doh: turns > 0 ? days / turns : NaN, gmroi: (sales - cogs) / avg };
  }

  function eoq(D, S, H) { return Math.sqrt(2 * D * S / H); }

  function costs(D, S, H, Q, safety) {
    return { orders: D / Q, ordering: D / Q * S, holding: Q / 2 * H, safetyHolding: safety * H };
  }

  function reorderPoint(D, days, lead, safety) { return Math.ceil(D / days * lead + safety - 1e-9); }

  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }

  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) { var td = document.createElement('td'); td.textContent = text; tr.appendChild(td); });
    body.appendChild(tr);
  }

  var PERF_IDS = ['iaTurns', 'iaDoh', 'iaGmroi', 'iaAvg', 'iaMargin'];
  var ORDER_IDS = ['iaEoq', 'iaRop', 'iaOrders', 'iaCycle', 'iaOrdCost', 'iaHoldCost', 'iaAvgUnits'];

  function dash(ids) { ids.forEach(function (id) { set(id, '–'); }); }

  function update() {
    var sales = num('iaSales'), cogs = num('iaCogs'), begin = num('iaBegin'), end = num('iaEnd'),
        D = num('iaDemand'), C = num('iaUnitCost'), S = num('iaOrderCost'), h = num('iaHolding'),
        lead = num('iaLead'), safety = num('iaSafety'), days = num('iaDays');
    if (document.getElementById('iaSafety').value.trim() === '') safety = 0;
    if (document.getElementById('iaDays').value.trim() === '') days = 365;
    var problems = [];

    // Section 1: performance
    var perfBad = [sales, cogs, begin, end].some(function (x) { return isNaN(x) || x < 0 || x > 1e12; });
    var daysBad = isNaN(days) || days < 1 || days > 366;
    if (perfBad) problems.push('Enter sales, cost of goods sold and inventory values of $0 or more.');
    else if (begin + end <= 0) problems.push('Enter a beginning or ending inventory above $0 to measure turnover.');
    if (daysBad) problems.push('Enter 1 to 366 selling days per year.');
    if (!perfBad && !daysBad && begin + end > 0) {
      var p = performance(sales, cogs, begin, end, days);
      set('iaTurns', one.format(p.turns) + '×');
      set('iaTurnsNote', 'Times you sell through your average stock in a year.');
      set('iaDoh', isNaN(p.doh) ? '–' : one.format(p.doh) + ' days');
      set('iaDohNote', isNaN(p.doh) ? 'No cost of goods sold, so stock never turns.' : 'How long the average item waits before it sells.');
      set('iaGmroi', money2.format(p.gmroi));
      set('iaGmroiNote', 'Gross margin earned per $1 of inventory at cost.');
      set('iaAvg', money.format(p.avg));
      set('iaMargin', money.format(sales - cogs) + (sales > 0 ? ' (' + one.format((sales - cogs) / sales * 100) + '%)' : ''));
    } else {
      dash(PERF_IDS); set('iaTurnsNote', ''); set('iaDohNote', ''); set('iaGmroiNote', '');
    }

    // Section 2: ordering
    var ordBad = false;
    if (isNaN(D) || D <= 0 || D > 1e12) { problems.push('Enter annual demand above 0 units.'); ordBad = true; }
    else if (isNaN(C) || C <= 0 || C > 1e9) { problems.push('Enter a cost per unit above $0.'); ordBad = true; }
    else if (isNaN(S) || S <= 0 || S > 1e9) { problems.push('Enter a cost per order above $0.'); ordBad = true; }
    else if (isNaN(h) || h <= 0 || h > 200) { problems.push('Enter a yearly holding cost above 0% (up to 200%).'); ordBad = true; }
    else if (isNaN(lead) || lead < 0 || lead > 365) { problems.push('Enter a lead time from 0 to 365 days.'); ordBad = true; }
    else if (isNaN(safety) || safety < 0 || safety > 1e12) { problems.push('Enter safety stock of 0 units or more.'); ordBad = true; }
    if (daysBad) ordBad = true;

    var tb = clearBody('iaTable');
    if (!ordBad) {
      var H = C * h / 100, Q = eoq(D, S, H);
      var c = costs(D, S, H, Q, safety);
      var rop = reorderPoint(D, days, lead, safety);
      set('iaEoq', units.format(Math.round(Q)) + ' units');
      set('iaEoqNote', 'Worth ' + money.format(Q * C) + ' at cost per order.');
      set('iaRop', units.format(rop) + ' units');
      set('iaRopNote', 'Reorder when stock falls to this level: ' + one.format(D / days * lead) + ' units of lead-time demand plus safety stock.');
      set('iaOrders', one.format(c.orders));
      set('iaCycle', one.format(days / c.orders) + ' days');
      set('iaOrdCost', money.format(c.ordering));
      set('iaHoldCost', money.format(c.holding + c.safetyHolding));
      set('iaAvgUnits', units.format(Math.round(Q / 2 + safety)));
      [0.5, 0.75, 1, 1.25, 1.5, 2].forEach(function (m) {
        var q = Math.max(1, Math.round(Q * m)), k = costs(D, S, H, q, 0);
        addRow(tb, [units.format(q) + (m === 1 ? ' (EOQ)' : ''), one.format(k.orders), money.format(k.ordering), money.format(k.holding), money.format(k.ordering + k.holding)]);
      });
    } else {
      dash(ORDER_IDS); set('iaEoqNote', ''); set('iaRopNote', '');
    }

    var error = document.getElementById('iaError');
    error.hidden = problems.length === 0;
    error.textContent = problems.join(' ');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('iaForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
